Blockly.Msg['COMMUNICATION_HC05_BLUETOOTH_GET_AT_COMMAND_TITLE'] = '[HC05 BT] AT - Parameterwert %1';
Blockly.Msg['COMMUNICATION_HC05_BLUETOOTH_GET_AT_COMMAND_TOOLTIP'] = IMG_MODULE_HC05_BT + Blockly.Tooltip.SEP + 'Ermöglicht das Abrufen der Parameterwerte des HC05 Bluetooth-Moduls durch Senden eines AT-Befehls.' + Blockly.Msg['COMMUNICATION_HC05_BLUETOOTH_KEY_HELPER'];
